Roll Random Beastmen NPC.command:
// Una macro per creare un NPC aleatorio, inviata come sussurro ai GMs nel organizzatore.

const namesTableID = game.tables.find(o => o.name === "La Cittadella Perduta: Nomi degli Uomini-bestia")._id;
const namesTable = await game.tables.get(namesTableID);
const namesResult = await namesTable.draw({displayChat: false});
const names = namesResult.results.pop().getChatText();

const appearanceTableID = game.tables.find(o => o.name === "La Cittella Perduta: Aspetto degli Uomini-bestia")._id;
const appearanceTable = await game.tables.get(appearanceTableID);
const appearanceResult = await appearanceTable.draw({displayChat: false});
const appearance = appearanceResult.results.pop().getChatText();

const behaviorTableID = game.tables.find(o => o.name === "La Cittadella Perduta: Comportamento degli Uomini-bestia")._id;
const behaviorTable = await game.tables.get(behaviorTableID);
const behaviorResult = await behaviorTable.draw({displayChat: false});
const behavior = behaviorResult.results.pop().getChatText();

const message = `<p>un @UUID[Compendium.shadowdark.monsters.Actor.k8tAgECWIzPIStGU] con aspetto <b>${appearance}</b> chiamato <b>${names}</b> 
di comportamento <b>${behavior}</b>.</p>`;

const chatData = {
  user: game.user._id,
  speaker: ChatMessage.getSpeaker(),
  content: message,
  whisper: game.users.filter(u => u.isGM).map(u => u._id),
};

ChatMessage.create(chatData, {});

