The Lost Citadel: Random Encounter Check.command:
// Una Macro per generare un incontro nella Cittadella Perduta e exibi-lo soltanto per il Mestre.;

const tableID = game.tables.find(o => o.name === "La Cittadella Perduta: Verifica Incontri Aleatori")._id;
const table = await game.tables.get(tableID);
await table.draw({ rollMode: CONST.DICE_ROLL_MODES.PRIVATE});
